ckup.restore(b,new ByteArrayInputStream(bytes),"fixture password123".toCharArray());check(b.state.getJSONObject("settingsSecrets").getString("apiKey").equals("sk-fixture-backup-key"),"AI credentials not restored");check(b.state.getJSONObject("deviceSecrets").getJSONObject("namespaces").getJSONObject("pikaMail").getJSONObject("config").getString("value").contains("fixture-google-refresh"),"Google credentials not restored");check(b.state.getString("ownerKey").equals("b".repeat(64))&&b.state.getString("device").equals("fixture-device-b"),"Backup transferred ownership");check(!b.state.has("forgetIntent"),"Backup transferred destructive lifecycle intent");check(b.restoredPending(),"Restore bypassed device confirmation");
