 static void mount(Instrumentation i)throws Exception{Context real=i.getTargetContext();i.startActivitySync(new Intent(real,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));long until=System.currentTimeMillis()+40000;PikaService service=null;while(System.currentTimeMillis()<until){service=PikaService.instance;if(service!=null&&service.ble.online&&!service.syncing&&!service.ble.deviceBusy)break;Thread.sleep(200);}check(service!=null&&service.ble.online&&!service.syncing,"Pika not ready for USB backup");BleTransport.Reply reply=service.ble.rpc("/api/manager/settings","POST",new JSONObject().put("action","usbMount").toString(),null);check(reply.status<400&&reply.json().optBoolean("saved"),"USB mount rejected");}
